using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"Research Agent Starting...");
Console.WriteLine($"Researching topic: {topic}");
Console.WriteLine();

// Configure the AI client with tool support
IChatClient innerClient = new OpenAI.OpenAIClient(
    Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set OPENAI_API_KEY environment variable"))
    .GetChatClient("gpt-4o")
    .AsIChatClient();

var researchTools = new ResearchTools();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (perform multiple searches with different queries)
        2. Taking notes on key findings as you discover them
        3. After gathering enough information, reviewing your notes and providing a comprehensive summary

        Always take notes on important findings before summarizing.
        Perform at least 2-3 different searches to get broad coverage of the topic.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}")
};

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n========== RESEARCH SUMMARY ==========\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n=======================================\n");

if (researchTools.Notes.Count > 0)
{
    Console.WriteLine($"[Agent took {researchTools.Notes.Count} notes during research]");
}

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private static readonly HttpClient Http = new();
    public List<string> Notes { get; } = [];

    [Description("Search the web for information on a query. Returns relevant search results.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var result = await Http.GetFromJsonAsync<JsonElement>(url);

            var output = new List<string>();

            var abstractText = result.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                output.Add($"Summary: {abstractText}");
                var source = result.GetProperty("AbstractSource").GetString();
                if (!string.IsNullOrWhiteSpace(source))
                    output.Add($"Source: {source}");
            }

            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
                    {
                        output.Add($"- {text.GetString()}");
                    }
                }
            }

            return output.Count > 0
                ? string.Join("\n", output)
                : $"No detailed results found for '{query}'. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note,
        [Description("Optional source or URL for the note")] string? source = null)
    {
        var entry = source is not null ? $"{note} (Source: {source})" : note;
        Notes.Add(entry);
        Console.WriteLine($"  [Tool] Note taken: {entry[..Math.Min(entry.Length, 80)]}...");
        return $"Note saved. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during research.")]
    public string GetNotes()
    {
        if (Notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  [Tool] Retrieving {Notes.Count} notes");
        return string.Join("\n", Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

