+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+
+            var result = await Http.GetFromJsonAsync<JsonElement>(url);
+
+            var output = new List<string>();
+
+            var abstractText = result.GetProperty("AbstractText").GetString();
+            if (!string.IsNullOrWhiteSpace(abstractText))
+            {
+                output.Add($"Summary: {abstractText}");
+                var source = result.GetProperty("AbstractSource").GetString();
+                if (!string.IsNullOrWhiteSpace(source))
+                    output.Add($"Source: {source}");
+            }
+
+            if (result.TryGetProperty("RelatedTopics", out var topics))
+            {
+                foreach (var topic in topics.EnumerateArray().Take(5))
+                {
+                    if (topic.TryGetProperty("Text", out var text) && !string.IsNullOrWhiteSpace(text.GetString()))
+                    {
+                        output.Add($"- {text.GetString()}");
+                    }
+                }
+            }
+
+            return output.Count > 0
+                ? string.Join("\n", output)
+                : $"No detailed results found for '{query}'. Try a different search query.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
